SELECT CASE WHEN YEAR(store_sales.sale_date) < 2024 THEN 'before_2024' WHEN YEAR(store_sales.sale_date) = 2024 THEN '2024' ELSE 'after_2024' END AS sale_cohort, MAX(inventory.quantity) AS max_quantity, MIN(inventory.last_restock) AS min_last_restock FROM inventory LEFT OUTER JOIN store_sales ON inventory.store_id = store_sales.store_id AND inventory.product_id = store_sales.product_id WHERE store_sales.revenue < 2000 GROUP BY CASE WHEN YEAR(store_sales.sale_date) < 2024 THEN 'before_2024' WHEN YEAR(store_sales.sale_date) = 2024 THEN '2024' ELSE 'after_2024' END ORDER BY sale_cohort;
